import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-10-30-rattrapage-additions/web-01-service-rattrape-et-delais-par-poste.jpg",m=JSON.parse('{"title":"Lot 2.13 — Rattrapage de la projection des additions + délais par poste (spec 08 §4, RG-REST-10/14, spec 12) — 30/10/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-10-30-rattrapage-additions.md","filePath":"generated/preuves/2026-10-30-rattrapage-additions.md","lastUpdated":null}'),i={name:"preuves/2026-10-30-rattrapage-additions.md"};function d(n,e,p,l,c,u){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="lot-2-13-—-rattrapage-de-la-projection-des-additions-delais-par-poste-spec-08-§4-rg-rest-10-14-spec-12-—-30-10-2026" tabindex="-1">Lot 2.13 — Rattrapage de la projection des additions + délais par poste (spec 08 §4, RG-REST-10/14, spec 12) — 30/10/2026 <a class="header-anchor" href="#lot-2-13-—-rattrapage-de-la-projection-des-additions-delais-par-poste-spec-08-§4-rg-rest-10-14-spec-12-—-30-10-2026" aria-label="Permalink to &quot;Lot 2.13 — Rattrapage de la projection des additions + délais par poste (spec 08 §4, RG-REST-10/14, spec 12) — 30/10/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-10-30-rattrapage-additions</code> · 1 image(s) · 0 trace(s)</p><div><p>Vraie stack : serveur local redémarré avec la migration V21 ; aucune action sur les caisses. Jusqu&#39;ici, la projection (lot 2.11) ne connaissait que les événements reçus <strong>après</strong> sa migration V20 : une seule journée de service, tables 1 et 2. Au démarrage, le serveur rejoue maintenant les événements d&#39;addition de l&#39;<code>event_log</code> qui n&#39;ont jamais été projetés (<code>order_projection_applied</code>), dans l&#39;ordre <code>server_seq</code>, tous tenants (datasource admin) — idempotent.</p><h2 id="web-—-page-«-service-»-apres-le-rattrapage" tabindex="-1">Web — page « Service » après le rattrapage <a class="header-anchor" href="#web-—-page-«-service-»-apres-le-rattrapage" aria-label="Permalink to &quot;Web — page « Service » après le rattrapage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;il faut voir</th></tr></thead><tbody><tr><td><a href="/VendoraSystem-docs/captures/2026-10-30-rattrapage-additions/web-01-service-rattrape-et-delais-par-poste.jpg">web-01-service-rattrape-et-delais-par-poste.jpg</a></td><td><strong>9 additions</strong> (8 ouvertes, 1 réglée) au lieu de 2 : toute la journée des lots 2.2 → 2.12 est revenue (tables 3 à 9 des séances de la nuit et du matin, avec leurs états : « 1 Prêt », « 2 Servi », « 1 Annulé »), CA additions 4,950, 31 couverts, offerts 0,800, délai moyen envoi → prêt 1 min 33 ; nouveau tableau <strong>par poste</strong> : Cuisine chaude 12 lignes, 3 prêtes, 1 min 33, cible 15 min, 9 en retard ; Bar 10 lignes, 0 prête, cible 5 min, 10 en retard (les additions de démonstration n&#39;ont jamais été servies)</td></tr></tbody></table><h2 id="serveur" tabindex="-1">Serveur <a class="header-anchor" href="#serveur" aria-label="Permalink to &quot;Serveur&quot;">​</a></h2><p>Journal au démarrage : <code>Rattrapage projection des additions : 43 événement(s) rejoué(s) depuis l&#39;event_log</code>. <code>GET /stores/&lt;magasin&gt;/orders?status=all</code> : 11 additions (dont 2 <code>MERGED</code>), les fusions des lots 2.8 et 2.12 bien rattachées à leurs cibles. <code>GET …/orders/kpis</code> : <code>byStation</code> renseigné (routage produit → poste explicite, sinon catégorie → poste, document <code>prep_stations</code> publié).</p><p>Test d&#39;intégration : projection effacée (admin, hors RLS) → <code>backfill()</code> rejoue ≥ 4 événements, second passage = 0, addition et lignes reconstruites à l&#39;identique ; indicateurs par poste (burger prêt en ~1 s sur « Cuisine chaude » cible 15 min, eau routée par produit sur « Bar », pas encore en retard).</p><h2 id="observations" tabindex="-1">Observations <a class="header-anchor" href="#observations" aria-label="Permalink to &quot;Observations&quot;">​</a></h2><ul><li>Le rejeu reproduit exactement l&#39;état courant : les upserts de la projection sont idempotents et les renumérotations d&#39;envois sont déterministes (lot 2.12) — l&#39;état « effacé puis rattrapé » est identique à l&#39;état « projeté au fil de l&#39;eau ».</li><li>« En retard » compte les lignes prêtes après la cible <strong>et</strong> celles encore en attente au-delà de la cible : les tables de démonstration jamais servies gonflent le compteur, ce qui est le comportement attendu en exploitation.</li><li>Les paiements fournisseur et pourboires sont déjà idempotents par clé (<code>sale_tip</code>, <code>payment_intent</code>) ; ils ne sont pas encore couverts par un rattrapage au démarrage.</li></ul></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-10-30-rattrapage-additions/web-01-service-rattrape-et-delais-par-poste.jpg" target="_blank"><img src="'+o+'" alt="web-01-service-rattrape-et-delais-par-poste.jpg" loading="lazy"></a><figcaption>web-01-service-rattrape-et-delais-par-poste.jpg</figcaption></figure></div>',5)])])}const v=a(i,[["render",d]]);export{m as __pageData,v as default};
